const fetch = require('node-fetch');
const url = 'https://jotterpad.app/publicApi/v1';
const token = 'API_KEY';
const frontmatter = `---
baseDocumentClass: article
documentClassArg: 12pt,a4paper
geometry: left=15mm,right=15mm,bindingoffset=0mm,top=8mm,bottom=15mm
noIndent: True
---

`; // 请参考 https://docs.jotterpad.app、https://jotterpad.app/app/templates 或 https://blog.jotterpad.app/flowise-jotterpads-print-engine/ 了解使用方法。

const input = frontmatter + ((typeof $input !== "undefined") ? $input : '');

const initOptions = {
	method: 'POST',
	headers: {
		'Authorization': `Apikey ${token}`,
		'Content-Type': 'application/json'
	},
	body: JSON.stringify({
		input,
		metadata: (typeof $metadata !== "undefined") ? $metadata : '',
		name: (typeof $name !== "undefined") ? $name : '无标题文档'
	})
};

const sleep = (ms) => {
	return new Promise((resolve) => {
		setTimeout(resolve, ms);
	});
}

try {
	const inType = (typeof $inType !== "undefined") ? $inType : 'md';
	const outType = (typeof $outType !== "undefined") ? $outType : 'pdf';
	const initResponse = await fetch(`${url}/exports/upload/${inType}/${outType}`, initOptions);
	const initJson = await initResponse.json();

	if (initJson.status === 'ok' && initJson.id) { 
		const exportId = initJson.id;
		const getOptions = {
			method: 'POST',
			headers: {
				'Authorization': `Apikey ${token}`,
				'Content-Type': 'application/json'
			},
			body: JSON.stringify({
				exportId
			})
		};

		for (let k = 0 ; k < 14 ; k++) {
			await sleep(k < 6 ? 20000 : 60000);
			const getResponse = await fetch(`${url}/exports/get`, getOptions);
			const getJson = await getResponse.json();
			if (getJson.status === 'ok' && getJson.exportedFile) {
                if (getJson.exportedFile.downloadUrl) {
    				return JSON.stringify({"url": getJson.exportedFile.downloadUrl, "input": input});
                }
			} else {
				console.error(getJson);
            	return JSON.stringify({"error": `原因：无法找到文档`});
			}
		}

	} else if (initJson.status === 'auth_required') {
		console.error(initJson);
		return JSON.stringify({"error": '原因：无效的API令牌'});
	} else if (initJson.status) {
		console.error(initJson);
		return JSON.stringify({"error": `原因：${initJson.status}`});
	} else {
		console.error(initJson);
    	return JSON.stringify({"error": `原因：未知`});
	}
} catch (error) {
	console.error(error);
	return JSON.stringify({"error": `原因：未知`});
}
